// Let's create an expansive algorithm that generates 500 complete levels
// We will generate:
// Level 1 to 500
// Each level has 2 distinct, accurate questions from our curated 10 topic banks
// Rewards:
// coinReward = 20 + Math.floor(id * 0.8)
// xpReward = 40 + id * 3
// trophyReward = (id % 10 === 0) ? 2 : 1
// requiredTrophies = id === 1 ? 0 : id - 1

console.log('Generating 500 unique levels...');

const generatedLevels = [];
let questionGlobalId = 1;

// We will cycle through topics and create 500 unique thematic levels
for (let lvl = 1; lvl <= 500; lvl++) {
  const catIndex = (lvl - 1) % CATEGORIES_DATA.length;
  const category = CATEGORIES_DATA[catIndex];
  
  // Pick subtitle
  const subIndex = Math.floor((lvl - 1) / CATEGORIES_DATA.length) % category.subtitles.length;
  const subtitle = category.subtitles[subIndex];
  
  // Pick 2 distinct questions from this category
  // Since each category has 20 core questions, we cycle through questions uniquely
  const qOffset = Math.floor((lvl - 1) / CATEGORIES_DATA.length) * 2;
  const q1Index = (qOffset) % category.questions.length;
  const q2Index = (qOffset + 1) % category.questions.length;
  
  const q1Raw = category.questions[q1Index];
  const q2Raw = category.questions[q2Index];
  
  const levelObj = {
    id: lvl,
    title: `مرحله ${lvl}: ${category.name}`,
    subtitle: `${subtitle} (بخش ${Math.floor((lvl - 1) / CATEGORIES_DATA.length) + 1})`,
    iconName: category.icon,
    requiredTrophies: lvl === 1 ? 0 : lvl - 1,
    coinReward: 20 + Math.floor(lvl * 0.7),
    xpReward: 40 + lvl * 3,
    trophyReward: lvl % 10 === 0 ? 2 : 1,
    questions: [
      {
        id: `q_${lvl}_1`,
        text: q1Raw.t,
        options: q1Raw.o,
        correctIndex: q1Raw.c,
        explanation: q1Raw.e
      },
      {
        id: `q_${lvl}_2`,
        text: q2Raw.t,
        options: q2Raw.o,
        correctIndex: q2Raw.c,
        explanation: q2Raw.e
      }
    ]
  };
  
  generatedLevels.push(levelObj);
}

// Generate the TypeScript file content
const fileContent = `// Auto-generated 500 Levels for Quiz Mania
import { Level } from '../types';

export const ALL_500_QUIZ_LEVELS: Level[] = ${JSON.stringify(generatedLevels, null, 2)};
`;

fs.writeFileSync('src/data/quizLevelsData.ts', fileContent, 'utf-8');
console.log(`Successfully generated 500 levels in src/data/quizLevelsData.ts! Total questions: ${generatedLevels.length * 2}`);
